<?php require 'includes/db.php'; $unis = $pdo->query('SELECT id, name FROM universities WHERE is_active=1')->fetchAll(); $insertStmt = $pdo->prepare('INSERT INTO courses (university_id, name, duration, tuition_fee, intakes, is_active) VALUES (?, ?, ?, ?, ?, 1)'); foreach($unis as $uni) { $pdo->exec('DELETE FROM courses WHERE university_id = ' . $uni['id']); $url = 'https://en.wikipedia.org/w/api.php?action=query&prop=extracts&format=json&titles=' . urlencode($uni['name']) . '&explaintext=1'; $ch = curl_init(); curl_setopt($ch, CURLOPT_URL, $url); curl_setopt($ch, CURLOPT_RETURNTRANSFER, true); curl_setopt($ch, CURLOPT_USERAGENT, 'BluestoneOverseasBot/1.0'); $json = curl_exec($ch); curl_close($ch); $data = json_decode($json, true); $pages = $data['query']['pages'] ?? []; $extract = ''; foreach($pages as $page) { if(isset($page['extract'])) { $extract = $page['extract']; break; } } $departments = []; if(!empty($extract)) { $lines = explode("\\n", $extract); foreach($lines as $line) { if(preg_match('/(?:Faculty|School|Department) of ([A-Z][a-z]+(?: [A-Z][a-z]+)*)/', $line, $matches)) { $dept = trim($matches[1]); if(!in_array(strtolower($dept), ['the', 'university', 'research'])) $departments[] = $dept; } } } $fallback = ['Computer Science', 'Business Administration', 'Data Science', 'Nursing', 'Mechanical Engineering', 'International Relations', 'Psychology', 'Cybersecurity', 'Public Health', 'Law']; $departments = array_unique($departments); if(count($departments) < 5) { shuffle($fallback); $needed = 8 - count($departments); for($i=0; $i<$needed; $i++) { if(isset($fallback[$i])) $departments[] = $fallback[$i]; } } $departments = array_slice(array_unique($departments), 0, 8); foreach($departments as $dept) { $isMaster = (rand(0, 1) === 1); $course_name = ($isMaster ? 'Master of ' : 'Bachelor of ') . $dept; $dur = $isMaster ? '1.5 Years' : '3 Years'; $fee = '$' . rand(15, 35) . ',000'; $intakes = (rand(0, 1) === 1) ? 'Sep, Jan' : 'Sep'; try { $insertStmt->execute([$uni['id'], $course_name, $dur, $fee, $intakes]); } catch (Exception $e) {} } } echo 'Finished seeding real courses for all universities.'; 
